using System;using System.IO;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public sealed class StudioImportDropHost:EditorWindow {
 internal StudioModelEditor editor;internal SceneView view;internal Action<StudioModelDocument> loaded;
 void OnGUI(){if(editor!=null)editor.HandleModelDrop(view,loaded);}
}
public static class StudioImportCameraValidation {
 static int checks,errors;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}
 static void Camera(SceneView view,Action action,string label){var pivot=view.pivot;var rotation=view.rotation;var size=view.size;var ortho=view.orthographic;var two=view.in2DMode;action();Check(Vector3.Distance(pivot,view.pivot)<1e-5f,label+" pivot");Check(Quaternion.Angle(rotation,view.rotation)<.001f,label+" rotation");Check(Mathf.Abs(size-view.size)<1e-5f,label+" zoom");Check(ortho==view.orthographic,label+" projection");Check(two==view.in2DMode,label+" 2D mode");}
 public static void Run(){string report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../import-camera-result.txt"));try{Application.logMessageReceived+=(s,t,k)=>{if(k==LogType.Assert||k==LogType.Exception||k==LogType.Error)errors++;};Validate();Check(errors==0,"Unexpected Unity errors: "+errors);File.WriteAllText(report,"PASS "+checks+" import-camera assertions");EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(report,e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Validate(){var fbx=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FrameProbe.fbx");Check(fbx,"Missing FBX");var source=GameObject.CreatePrimitive(PrimitiveType.Cube);source.transform.position=new Vector3(100,50,-80);var mesh=source.GetComponent<MeshFilter>().sharedMesh;var view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();var host=ScriptableObject.CreateInstance<StudioImportDropHost>();view.Show();host.Show();try{for(int k=0;k<3;k++){using(var editor=new StudioModelEditor(()=>{})){Action<StudioModelDocument> load=d=>{editor.Load(d);view.Bind(editor.Scene);editor.Frame(view);};editor.BindModelCommands(view,load);view.in2DMode=k==2;view.orthographic=k>0;view.LookAtDirect(new Vector3(7,-4,12),Quaternion.Euler(21,63,4),7.2f);Camera(view,()=>editor.ImportModel(source,load),"First import "+k);Check(editor.Document&&editor.Document.nodes.Count>0,"First import missing");Camera(view,()=>editor.ImportModel(fbx,load),"FBX append "+k);Camera(view,()=>editor.ImportDroppedSource(mesh,load),"Mesh append "+k);host.editor=editor;host.view=view;host.loaded=load;DragAndDrop.PrepareStartDrag();DragAndDrop.objectReferences=new Object[]{source};DragAndDrop.paths=Array.Empty<string>();int count=editor.Document.nodes.Count;Camera(view,()=>host.SendEvent(new Event{type=EventType.DragPerform,mousePosition=new Vector2(30,30)}),"Viewport drop "+k);Check(editor.Document.nodes.Count>count,"Drop did not import");DragAndDrop.objectReferences=Array.Empty<Object>();host.editor=null;}}}finally{host.Close();view.Close();Object.DestroyImmediate(source);}}
}
